import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return fail('CUSTOMER_NOT_FOUND');

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!isValidQty(line.qty)) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return fail('UNKNOWN_SKU');

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(newLine);
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

function isValidDate(dateStr) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
  if (!match) return false;

  const date = new Date(dateStr + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(dateStr);
}

function isValidQty(qty) {
  return Number.isInteger(qty) && qty > 0;
}

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the total for a single line item (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
function lineDiscount(line) {
  if (!line.discountPercent) return 0;
  const total = lineTotal(line);
  const discount = (total * line.discountPercent) / 100;
  return Math.max(0, discount);
}

/**
 * Calculate invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!isValidQty(qty)) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const customerResult = getCustomer(invoice.customerId);
  const customer = customerResult.ok ? customerResult.value : null;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingIndex >= 0) {
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
    if (discountPercent !== undefined) {
      newLines[existingIndex].discountPercent = discountPercent;
    }
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    } else if (customer) {
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }

    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const index = invoice.lines.findIndex((line) => line.sku === sku);
  if (index < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to "issued".
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array<any> }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already in use
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    number,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

