test('invoiceTotals: single line item', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
    ],
  };

  const result = invoiceTotals(invoice);
  assert.deepEqual(result, { subtotal: 95000, discount: 0, total: 95000 });
});

test('invoiceTotals: multiple line items', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 5, unitPrice: 8500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const result = invoiceTotals(invoice);
  assert.deepEqual(result, { subtotal: 257500, discount: 0, total: 257500 });
});

