  const invoice = {
    lines: [
      { qty: 1, unitPrice: 50 },
      { qty: 2, unitPrice: 100 },
      { qty: 3, unitPrice: 250 },
    ],
  };

  const result = invoiceTotals(invoice);
  const expected = 50 + 200 + 750;
  assert.deepEqual(result, { subtotal: expected, discount: 0, total: expected });
});

test('invoiceTotals: large amounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 120000 },
      { qty: 50, unitPrice: 245000 },
    ],
  };

  const result = invoiceTotals(invoice);
  assert.deepEqual(result, { subtotal: 24250000, discount: 0, total: 24250000 });
});

