      { qty: 3, unitPrice: 250, vatRate: 0 },
    ],
  };

  const result = invoiceTotals(invoice);
  const subtotal = 50 + 200 + 750;
  const vat = Math.round((50 * 0.21 * 100) / 100) + Math.round((200 * 0.09 * 100) / 100) + Math.round((750 * 0 * 100) / 100);
