test('lineTotal: single unit', () => {
  const line = { qty: 1, unitPrice: 9500 };
  assert.equal(lineTotal(line), 9500);
});

test('lineTotal: multiple units', () => {
  const line = { qty: 10, unitPrice: 9500 };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal: large quantities', () => {
  const line = { qty: 1000, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000000);
