test('invoiceTotals: VAT rounding per line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 3 },
      { sku: 'PHOTO-LIC', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const line1Subtotal = 980 * 3;
  const line2Subtotal = 996 * 2;
  const line1Vat = Math.round(line1Subtotal * 0.21 * 100) / 100;
  const line2Vat = Math.round(line2Subtotal * 0.21 * 100) / 100;
  const expectedVat = line1Vat + line2Vat;
  assert.equal(totals.vat, expectedVat);
});

