test('invoiceTotals: large amounts with VAT', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 120000, vatRate: 21 },
      { qty: 50, unitPrice: 245000, vatRate: 21 },
    ],
  };

  const result = invoiceTotals(invoice);
  const subtotal = 24250000;
  const vat = 24250000 * 0.21;
  assert.deepEqual(result, { subtotal, discount: 0, vat, total: subtotal + vat });
});

test('invoiceTotals: from createInvoice result', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(invoice.ok, true);

  const totals = invoiceTotals(invoice.value);
  const expectedSubtotal = 10 * 9500 + 5 * 8500;
  const expectedDiscount = expectedSubtotal * 0.05;
  const amountAfterDiscount = expectedSubtotal - expectedDiscount;
  const expectedVat = Math.round((amountAfterDiscount * 0.21 * 100) / 100);
  assert.deepEqual(totals, { subtotal: expectedSubtotal, discount: expectedDiscount, vat: expectedVat, total: expectedSubtotal - expectedDiscount + expectedVat });
});

