test('invoiceTotals: multiple lines with mixed discounts and VAT', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 2, discountPercent: 25 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 95000 + 42500 + 12000;
  const discount = 9500 + (42500 * 0.05) + 3000;
  const line1Vat = Math.round(((95000 - 9500) * 0.21 * 100) / 100);
  const line2Vat = Math.round(((42500 - 42500 * 0.05) * 0.21 * 100) / 100);
  const line3Vat = Math.round(((12000 - 3000) * 0.21 * 100) / 100);
  const vat = line1Vat + line2Vat + line3Vat;
  assert.deepEqual(totals, { subtotal, discount, vat, total: subtotal - discount + vat });
});

