    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'DES-HOUR',
